CREATE VIEW dbo.IV_Q$VENDA_EQUIPAMENTO ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario, DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao, SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , VENDA_COMPRADOR, VENDA_JDQUOTE, VENDA_TIPO_VENDA, VENDA_DATA_PEDIDO, VENDA_TIPO_EQUIPAMEN, VENDA_MARCA_EQUIPAME, VENDA_MODELO_EQUIPAM, VENDA_QTDE_EQUIPAMEN, VENDA_LASTRO_DIANT, VENDA_LASTRO_TRASEIR, VENDA_RODADO_DIANT, VENDA_RODADO_TRASEIR, VENDA_QTDE_VCR, VENDA_QTDE_VCR_DLX, VENDA_MEDIDA_BITOLA, VENDA_CREEPER, VENDA_INST_CABINE, VENDA_AMS, RECEPTOR, VENDA_AMS_ATIVACAO, VENDA_AMS_MONITOR, VENDA_AMS_VOLANTE, VENDA_AMS_RADIO, VENDAS_AMS_CONECT, VENDA_AMS_CONFIG_ADC, VENDA_VALOR_TOTAL, VENDA_VALOR_SINAL, VENDA_DATA_SINAL, VENDA_VALOR_FINANC, VENDA_FORMA_PAGTO, VENDA_INST_FINANC, VENDA_LINHA_CREDITO, VENDA_CONTATO_BANCO, VENDA_COMPARTILHADA, VENDA_CONSULTOR_1, VENDA_CONSULTOR_2, VENDA_PRIMEIRO_JD, DESCONTO_INCONDICION, VENDA_MARGEM_NEGOC, VENDA_COTACAO, VENDA_FDD, VENDA_CHASSI, VENDA_INFO_PREP, VENDA_ENTREG_PREP, VENDA_DATA_ENTREGA, VENDA_DESCONTO_INC, VENDA_TRANSPORTADORA, VENDA_VALOR_FRETE)    AS SELECT TBASE.SEQPESSOA, TBASE.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO, QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS, QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO, QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.VENDA_COMPRADOR, TABF.VENDA_JDQUOTE, TABF.VENDA_TIPO_VENDA, TABF.VENDA_DATA_PEDIDO, TABF.VENDA_TIPO_EQUIPAMEN, TABF.VENDA_MARCA_EQUIPAME, TABF.VENDA_MODELO_EQUIPAM, TABF.VENDA_QTDE_EQUIPAMEN, TABF.VENDA_LASTRO_DIANT, TABF.VENDA_LASTRO_TRASEIR, TABF.VENDA_RODADO_DIANT, TABF.VENDA_RODADO_TRASEIR, TABF.VENDA_QTDE_VCR, TABF.VENDA_QTDE_VCR_DLX, TABF.VENDA_MEDIDA_BITOLA, TABF.VENDA_CREEPER, TABF.VENDA_INST_CABINE, TABF.VENDA_AMS, TABF.RECEPTOR, TABF.VENDA_AMS_ATIVACAO, TABF.VENDA_AMS_MONITOR, TABF.VENDA_AMS_VOLANTE, TABF.VENDA_AMS_RADIO, TABF.VENDAS_AMS_CONECT, TABF.VENDA_AMS_CONFIG_ADC, TABF.VENDA_VALOR_TOTAL, TABF.VENDA_VALOR_SINAL, TABF.VENDA_DATA_SINAL, TABF.VENDA_VALOR_FINANC, TABF.VENDA_FORMA_PAGTO, TABF.VENDA_INST_FINANC, TABF.VENDA_LINHA_CREDITO, TABF.VENDA_CONTATO_BANCO, TABF.VENDA_COMPARTILHADA, TABF.VENDA_CONSULTOR_1, TABF.VENDA_CONSULTOR_2, TABF.VENDA_PRIMEIRO_JD, TABF.DESCONTO_INCONDICION, TABF.VENDA_MARGEM_NEGOC, TABF.VENDA_COTACAO, TABF.VENDA_FDD, TABF.VENDA_CHASSI, TABF.VENDA_INFO_PREP, TABF.VENDA_ENTREG_PREP, TABF.VENDA_DATA_ENTREGA, TABF.VENDA_DESCONTO_INC, TABF.VENDA_TRANSPORTADORA, TABF.VENDA_VALOR_FRETE   FROM IV_Q_VENDA_EQUIPAMENTO TABF 	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO 	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO 	JOIN GE_PESSOA TBASE ON TBASE.SEQPESSOA = QST.SEQPESSOA  